import '../constants/tiers.dart';

/// Represents a multiple-choice clarifying question generated by an Agent,
/// modeled after Antigravity's interactive `ask_question` tool.
class AgentQuestion {
  final String id;
  final String question;
  final List<String> options;
  final bool isMultiSelect;
  String selectedOption;
  String customWriteIn;

  AgentQuestion({
    required this.id,
    required this.question,
    required this.options,
    this.isMultiSelect = false,
    String? selectedOption,
    this.customWriteIn = '',
  }) : selectedOption = selectedOption ?? '';

  /// Effective user answer (prefers customWriteIn if non-empty).
  String get effectiveAnswer =>
      customWriteIn.trim().isNotEmpty ? customWriteIn.trim() : selectedOption;

  Map<String, dynamic> toJson() => {
        'id': id,
        'question': question,
        'options': options,
        'isMultiSelect': isMultiSelect,
        'selectedOption': selectedOption,
        'customWriteIn': customWriteIn,
      };

  factory AgentQuestion.fromJson(Map<String, dynamic> json) {
    final opts = (json['options'] as List?)?.map((e) => e.toString()).toList() ?? const <String>[];
    return AgentQuestion(
      id: json['id']?.toString() ?? 'q',
      question: json['question']?.toString() ?? '',
      options: opts,
      isMultiSelect: json['isMultiSelect'] == true,
      selectedOption: json['selectedOption']?.toString(),
      customWriteIn: json['customWriteIn']?.toString() ?? '',
    );
  }
}

/// Sequential production phase tracks in the Rolling Phase Release model:
/// 1. Prototype -> 2. MVP Track (1 Release per Beat) -> 3. Vertical Slice -> 4. Full Production.
enum ProductionPhase {
  prototype(
    label: 'PHASE 1 · PROTOTYPE',
    shortName: 'Prototype',
    summary: 'Define and playtest the Core Game Loop in a greybox sandbox.',
    unlockCondition: 'Active in Stage 1',
  ),
  mvp(
    label: 'PHASE 2 · MVP RELEASES',
    shortName: 'MVP Track',
    summary: 'Build 1 focused MVP Release for each proven Core Loop Epic.',
    unlockCondition: 'Unlocks after Prototype completes',
  ),
  verticalSlice(
    label: 'PHASE 3 · VERTICAL SLICE',
    shortName: 'Vertical Slice',
    summary: 'Combine all completed MVP Beats into 1 fully polished Gold Standard level.',
    unlockCondition: 'Unlocks after all MVP Releases complete',
  ),
  fullProduction(
    label: 'PHASE 4 · FULL PRODUCTION',
    shortName: 'Full Production',
    summary: 'Reuse the Rough → Polish release pattern across the remaining world and content.',
    unlockCondition: 'Unlocks after Vertical Slice completes',
  );

  final String label;
  final String shortName;
  final String summary;
  final String unlockCondition;

  const ProductionPhase({
    required this.label,
    required this.shortName,
    required this.summary,
    required this.unlockCondition,
  });
}

/// Blueprint produced during Stage 1 (Initial Project Concept Creation).
/// Combines the 9-section structured Project Concept (`Goal`, `Game Spec`,
/// `Tech Spec`, `Design Pillars`, `Trade-Offs`, `Core Loop`, `Out of Scope`,
/// `Done When`, `Prototype Release`) with section-focused Agent guidance.
class ProjectConceptBlueprint {
  String title;
  String sparkIdea;
  List<AgentQuestion> questions;
  String goal;
  List<String> gameSpec;
  List<String> techSpec;
  List<String> designPillars;
  List<String> tradeOffs;
  List<String> coreLoopBeats;
  List<String> exclusions;
  String doneWhen;
  ReleaseScope firstReleasePreset;
  List<String> releaseTrainTitles;
  bool isInterviewComplete;
  String? lastAgentReply;
  List<String> lastUpdatedFields;
  Map<String, List<String>> sectionOptions;

  ProjectConceptBlueprint({
    required this.title,
    required this.sparkIdea,
    required this.questions,
    required String goal,
    this.gameSpec = const [
      '2D Top-Down',
      'Twin-Stick (WASD + Aim)',
      'Singleplayer',
      'Single-Screen Wave Arena',
    ],
    this.techSpec = const [
      'Godot 4 (2D)',
      'PC (Steam / Desktop)',
      '2D Sprites + Particles',
      'Offline-Only Local Save',
    ],
    this.designPillars = const [
      'Decisive Momentum: Every cycle rewards decisive movement and timing over hesitation',
      'Instant Recovery: Mistakes feel immediately readable and recoverable in a single button press',
      'Responsive Controls: Core controls feel responsive from the very first second on screen',
    ],
    this.tradeOffs = const [
      'Immediate arcade responsiveness over realistic physics inertia',
      'Readable greybox clarity over complex visual shaders in v0.1',
      'Fast 1-key loop reset over multi-screen menu flows',
    ],
    required this.coreLoopBeats,
    required this.exclusions,
    required this.doneWhen,
    this.firstReleasePreset = ReleaseScope.featurePrototype,
    required this.releaseTrainTitles,
    this.isInterviewComplete = false,
    this.lastAgentReply,
    this.lastUpdatedFields = const [],
    Map<String, List<String>>? sectionOptions,
  })  : goal = sanitizeGoalText(goal),
        sectionOptions = sectionOptions ?? <String, List<String>>{} {
    if (designPillars.isNotEmpty) {
      designPillars = [
        for (int i = 0; i < designPillars.length; i++)
          ensureNamedPillar(designPillars[i], i),
      ];
    }
    // Auto-repair any legacy Beat 01 that copy-pasted raw "instead of..." user instructions
    if (coreLoopBeats.isNotEmpty &&
        _legacyCoreFocusInsteadRegex.hasMatch(coreLoopBeats.first)) {
      coreLoopBeats[0] =
          'Primary Vehicle & Loadout Control: Spawn in the arena and test responsive steering, boost, and primary fire';
    }
  }

  static final RegExp _legacyCoreFocusInsteadRegex = RegExp(
    r'^Core Focus:\s*instead of\b',
    caseSensitive: false,
  );
  static final RegExp _genericPillarLabelRegex = RegExp(
    r'^(?:pillar|design\s+pillar|p)\s*[#·\-]?\s*\d*$',
    caseSensitive: false,
  );
  static final RegExp _vehicalsTypoRegex = RegExp(
    r'\bvehicals\b',
    caseSensitive: false,
  );
  static final RegExp _vehicalTypoRegex = RegExp(
    r'\bvehical\b',
    caseSensitive: false,
  );
  static final RegExp _enemysTypoRegex = RegExp(
    r'\benemys\b',
    caseSensitive: false,
  );
  static final RegExp _keepSectionsQuotedSuffixRegex = RegExp(
    r'"?\.?\s*Keep all other sections intact.*$',
    caseSensitive: false,
  );
  static final RegExp _responsiveControlsSuffixRegex = RegExp(
    r'"\s*with responsive controls and clear feedback\.?$',
    caseSensitive: false,
  );
  static final RegExp _sectionWrapperPrefixRegex = RegExp(
    r'^.*?\[Section\s+\d+\s+[^\]]+\]\s*(Update ONLY the [^\n]+?:\s*)?',
    caseSensitive: false,
  );
  static final RegExp _keepSectionsPlainSuffixRegex = RegExp(
    r'\.?\s*Keep all other sections intact.*$',
    caseSensitive: false,
  );
  static final RegExp _rawInsteadPrototypeRegex = RegExp(
    r'^Build a (.+?) prototype focused on ["\s]*instead of (?:a |an |the )?([a-zA-Z0-9\s-]+?)\s+(?:we\s+use|use|using|have|play\s+as)\s+([a-zA-Z0-9\s-]+?)\.?\s*["\s]*with responsive controls and clear feedback\.?$',
    caseSensitive: false,
  );
  static final RegExp _longParenBlockRegex = RegExp(r'\([^()]{12,}\)');
  static final RegExp _longParenStripRegex = RegExp(r'\s*\([^()]{12,}\)');

  /// Parses a Design Pillar string into a concrete `(title, body)` pair,
  /// synthesizing a descriptive 2-3 word name whenever the raw pillar lacks a `Title:` prefix
  /// (or uses a generic `Pillar 01` placeholder).
  static ({String title, String body}) parsePillarTitleAndBody(
    String raw,
    int index,
  ) {
    final clean = raw.trim();
    if (clean.isEmpty) {
      const fallbackTitles = [
        'Core Loop Tension',
        'Tactile Control Feel',
        'Readable Threat Cues',
        'Fast Loop Recovery',
      ];
      return (
        title: fallbackTitles[index % fallbackTitles.length],
        body: 'Every action provides immediate, readable player feedback.',
      );
    }

    String body = clean;
    final colonIdx = clean.indexOf(':');
    if (colonIdx > 0 && colonIdx < 48 && colonIdx < clean.length - 1) {
      final head = clean.substring(0, colonIdx).trim();
      final tail = clean.substring(colonIdx + 1).trim();
      final isGenericPillarLabel = _genericPillarLabelRegex.hasMatch(head);
      if (head.isNotEmpty && tail.isNotEmpty && !isGenericPillarLabel) {
        return (title: head, body: tail);
      }
      if (tail.isNotEmpty) {
        body = tail;
      }
    }

    final lower = body.toLowerCase();
    String synthesizedTitle;
    if (lower.contains('cargo') || lower.contains('courier')) {
      synthesizedTitle = 'High-Stakes Cargo';
    } else if (lower.contains('gamble') ||
        lower.contains('greed') ||
        lower.contains('high-stakes') ||
        lower.contains('stakes') ||
        (lower.contains('risk') && lower.contains('survival'))) {
      synthesizedTitle = 'High-Stakes Tension';
    } else if (lower.contains('scaveng') ||
        lower.contains('loot weight') ||
        lower.contains('weapon handling') ||
        lower.contains('tactile') ||
        lower.contains('grounded and impactful')) {
      synthesizedTitle = 'Tactile Scavenging';
    } else if (lower.contains('careful observation') ||
        lower.contains('reckless rushing') ||
        (lower.contains('dangerous') && lower.contains('unpredictable'))) {
      synthesizedTitle = 'Deliberate Threat Reading';
    } else if (lower.contains('momentum') ||
        lower.contains('velocity') ||
        lower.contains('flow-state') ||
        lower.contains('stop moving') ||
        lower.contains('wall-run') ||
        lower.contains('parkour')) {
      synthesizedTitle = 'Flow-State Momentum';
    } else if (lower.contains('telegraph') ||
        lower.contains('readable') ||
        lower.contains('chaos') ||
        lower.contains('clarity')) {
      synthesizedTitle = 'Readable Threat Cues';
    } else if (lower.contains('recover') ||
        lower.contains('mistake') ||
        lower.contains('failure') ||
        lower.contains('teaches') ||
        lower.contains('repeatable')) {
      synthesizedTitle = 'Fast Fair Recovery';
    } else if (lower.contains('decisive') || lower.contains('hesitation')) {
      synthesizedTitle = 'Decisive Momentum';
    } else if (lower.contains('position') || lower.contains('tactical')) {
      synthesizedTitle = 'Tactical Positioning';
    } else if (lower.contains('control') ||
        lower.contains('responsive') ||
        lower.contains('first second')) {
      synthesizedTitle = 'Immediate Control Feel';
    } else if (lower.contains('chain') ||
        lower.contains('combo') ||
        lower.contains('mastery')) {
      synthesizedTitle = 'Chain-Reaction Mastery';
    } else {
      const fallbackTitles = [
        'Core Loop Tension',
        'Tactile Control Feel',
        'Readable Threat Cues',
        'Fast Loop Recovery',
      ];
      synthesizedTitle = fallbackTitles[index % fallbackTitles.length];
    }

    return (title: synthesizedTitle, body: body);
  }

  /// Ensures a Design Pillar string always carries a concrete `Name: Experience` prefix.
  static String ensureNamedPillar(String raw, int index) {
    final parsed = parsePillarTitleAndBody(raw, index);
    return '${parsed.title}: ${parsed.body}';
  }

  /// Normalizes common game-dev typos in conversational user input (e.g. "vehicals" -> "vehicles").
  static String normalizeCommonTypos(String input) {
    return input
        .replaceAll(_vehicalsTypoRegex, 'vehicles')
        .replaceAll(_vehicalTypoRegex, 'vehicle')
        .replaceAll(_enemysTypoRegex, 'enemies');
  }

  /// Strips leaked `[Section 01 Goal]...` or `to apply this choice: "..."` prompt wrappers,
  /// raw `"focused on instead of X we use Y"` copy-pastes, and stacked parenthetical brain-dump notes
  /// from a Goal string so saved or live projects always display a clean, readable 1-sentence Goal.
  static String sanitizeGoalText(String rawGoal) {
    var clean = normalizeCommonTypos(rawGoal.trim());
    if (clean.isEmpty) return clean;

    final lower = clean.toLowerCase();
    const choiceMarker = 'to apply this choice:';
    final choiceIdx = lower.indexOf(choiceMarker);
    if (choiceIdx != -1) {
      var afterMarker = clean.substring(choiceIdx + choiceMarker.length).trim();
      if (afterMarker.startsWith('"') || afterMarker.startsWith("'")) {
        afterMarker = afterMarker.substring(1).trim();
      }
      // Strip trailing `. Keep all other sections intact...` and wrapper suffixes
      afterMarker = afterMarker.replaceFirst(
        _keepSectionsQuotedSuffixRegex,
        '',
      );
      afterMarker = afterMarker.replaceFirst(
        _responsiveControlsSuffixRegex,
        '',
      );
      if (afterMarker.endsWith('"') || afterMarker.endsWith("'")) {
        afterMarker = afterMarker.substring(0, afterMarker.length - 1).trim();
      }
      if (afterMarker.isNotEmpty) {
        clean = afterMarker;
      }
    }

    // Strip any remaining `[Section 01 Goal]` prefix or `focused on "[Section ..."` wrapper
    clean = clean.replaceFirst(_sectionWrapperPrefixRegex, '');
    clean = clean.replaceFirst(_keepSectionsPlainSuffixRegex, '');

    // Repair raw "Build a <Title> prototype focused on instead of <X> we use <Y> with responsive controls..."
    final rawInsteadMatch = _rawInsteadPrototypeRegex.firstMatch(clean);
    if (rawInsteadMatch != null) {
      final rawTitle = rawInsteadMatch.group(1)!.trim();
      final oldSubject = rawInsteadMatch.group(2)!.trim();
      final newSubject = rawInsteadMatch.group(3)!.trim();
      final singularNew = newSubject.toLowerCase().endsWith('s') && newSubject.length > 3
          ? newSubject.substring(0, newSubject.length - 1)
          : newSubject;
      final capNew = singularNew[0].toUpperCase() + singularNew.substring(1);
      final updatedTitle = rawTitle.replaceAll(
        RegExp(RegExp.escape(oldSubject), caseSensitive: false),
        capNew,
      );
      clean =
          'Single-Arena Loop: Build a playable $updatedTitle prototype where you control $newSubject, weave through arena hazards, and clear escalating enemy waves.';
    }

    // Strip stacked parenthetical brain-dump notes if more than 1 parenthetical block appears
    final parenMatches = _longParenBlockRegex.allMatches(clean).length;
    if (parenMatches >= 2) {
      clean = clean.replaceAll(_longParenStripRegex, '').trim();
    }

    if (clean.isNotEmpty && !clean.endsWith('.')) {
      clean = '$clean.';
    }
    return clean;
  }

  /// Formats the Project Concept into the strict 3-part Scope & Goal layout.
  String toFormattedScopeSection() {
    final inScopeLines = coreLoopBeats.map((b) => '• $b').join('\n');
    final outScopeLines = exclusions.map((e) => '• $e').join('\n');
    return 'Goal: $goal\n\n'
        'In Scope:\n$inScopeLines\n\n'
        'Out of Scope:\n$outScopeLines\n\n'
        'Done When: $doneWhen';
  }

  /// Formats the complete 8-section Project Concept Blueprint into Markdown for export.
  String toFullMarkdownSpec() {
    final buf = StringBuffer()
      ..writeln('Goal: $goal')
      ..writeln();
    if (gameSpec.isNotEmpty) {
      buf.writeln('Game Spec: ${gameSpec.join(' · ')}');
    }
    if (techSpec.isNotEmpty) {
      buf.writeln('Tech Spec: ${techSpec.join(' · ')}');
    }
    if (designPillars.isNotEmpty) {
      buf
        ..writeln()
        ..writeln('Design Pillars:')
        ..writeln(designPillars.map((p) => '• $p').join('\n'));
    }
    if (tradeOffs.isNotEmpty) {
      buf
        ..writeln()
        ..writeln('Trade-Offs:')
        ..writeln(tradeOffs.map((t) => '• $t').join('\n'));
    }
    buf
      ..writeln()
      ..writeln('In Scope:')
      ..writeln(coreLoopBeats.map((b) => '• $b').join('\n'))
      ..writeln()
      ..writeln('Out of Scope:')
      ..writeln(exclusions.map((e) => '• $e').join('\n'))
      ..writeln()
      ..write('Done When: $doneWhen');
    return buf.toString();
  }

  Map<String, dynamic> toJson() => {
        'title': title,
        'sparkIdea': sparkIdea,
        'questions': questions.map((q) => q.toJson()).toList(),
        'goal': goal,
        'gameSpec': gameSpec,
        'techSpec': techSpec,
        'designPillars': designPillars,
        'tradeOffs': tradeOffs,
        'coreLoopBeats': coreLoopBeats,
        'exclusions': exclusions,
        'doneWhen': doneWhen,
        'firstReleasePreset': firstReleasePreset.name,
        'releaseTrainTitles': releaseTrainTitles,
        'isInterviewComplete': isInterviewComplete,
        if (lastAgentReply != null) 'lastAgentReply': lastAgentReply,
        'lastUpdatedFields': lastUpdatedFields,
        'sectionOptions': sectionOptions,
      };

  factory ProjectConceptBlueprint.fromJson(Map<String, dynamic> json) {
    final rawOpts = json['sectionOptions'] as Map<String, dynamic>?;
    final parsedOpts = <String, List<String>>{};
    if (rawOpts != null) {
      rawOpts.forEach((key, value) {
        if (value is List) {
          parsedOpts[key] = value.map((e) => e.toString()).toList();
        }
      });
    }
    return ProjectConceptBlueprint(
      title: json['title']?.toString() ?? 'Untitled Project',
      sparkIdea: json['sparkIdea']?.toString() ?? '',
      questions: (json['questions'] as List?)
              ?.whereType<Map<String, dynamic>>()
              .map(AgentQuestion.fromJson)
              .toList() ??
          <AgentQuestion>[],
      goal: json['goal']?.toString() ?? '',
      gameSpec: (json['gameSpec'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const [
            '2D Top-Down',
            'Twin-Stick (WASD + Aim)',
            'Singleplayer',
            'Single-Screen Wave Arena',
          ],
      techSpec: (json['techSpec'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const [
            'Godot 4 (2D)',
            'PC (Steam / Desktop)',
            '2D Sprites + Particles',
            'Offline-Only Local Save',
          ],
      designPillars: (json['designPillars'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      tradeOffs: (json['tradeOffs'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      coreLoopBeats: (json['coreLoopBeats'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          <String>[],
      exclusions: (json['exclusions'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          <String>[],
      doneWhen: json['doneWhen']?.toString() ?? '',
      firstReleasePreset: ReleaseScope.values.firstWhere(
        (s) => s.name == json['firstReleasePreset'],
        orElse: () => ReleaseScope.featurePrototype,
      ),
      releaseTrainTitles: (json['releaseTrainTitles'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          <String>['v0.1: Core Movement & Game Loop - Prototype'],
      isInterviewComplete: json['isInterviewComplete'] == true,
      lastAgentReply: json['lastAgentReply']?.toString(),
      lastUpdatedFields: (json['lastUpdatedFields'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      sectionOptions: parsedOpts,
    );
  }
}

/// Lifecycle state of a Feature across evolving releases (`v0.1` -> `v0.2` -> `v1.0+`).
enum FeatureLifecycleStatus {
  /// Newly introduced in this release (or promoted from prior Out of Scope).
  newFeature,

  /// Built in an earlier release and receiving new upgrade Checkpoints in this release.
  upgrade,

  /// Built in an earlier release and untouched in this release (`0h` delta work).
  stable,

  /// Temporary testbed from an earlier release superseded by a real system in this release.
  superseded;

  static FeatureLifecycleStatus fromString(String? raw) {
    final clean = (raw ?? '').trim().toLowerCase();
    if (clean.contains('upgrade') || clean.contains('evolve')) {
      return FeatureLifecycleStatus.upgrade;
    }
    if (clean.contains('stable') || clean.contains('frozen')) {
      return FeatureLifecycleStatus.stable;
    }
    if (clean.contains('supersed') || clean.contains('retire') || clean.contains('archive')) {
      return FeatureLifecycleStatus.superseded;
    }
    return FeatureLifecycleStatus.newFeature;
  }
}

/// A proposed Feature stub inside a Release Blueprint Beat.
/// The user can toggle `included` on/off at the Confirmation Gate;
/// unchecked features automatically move into `Out of Scope` (YAGNI).
class ProposedFeatureBlueprint {
  String id;
  String title;
  String goal;
  String doneWhen;
  int estimatedHours;
  bool included;
  FeatureLifecycleStatus lifecycle;
  String originVersion;
  String? supersedesFeatureTitle;
  List<String> inScope;
  List<String> outOfScope;
  List<String> tuningParams;
  List<String> edgeCases;
  List<ProposedCheckpointBlueprint> checkpoints;

  ProposedFeatureBlueprint({
    required this.id,
    required this.title,
    required this.goal,
    required this.doneWhen,
    this.estimatedHours = 4,
    this.included = true,
    this.lifecycle = FeatureLifecycleStatus.newFeature,
    this.originVersion = 'v0.1',
    this.supersedesFeatureTitle,
    this.inScope = const [],
    this.outOfScope = const [],
    this.tuningParams = const [],
    this.edgeCases = const [],
    this.checkpoints = const [],
  });

  bool get isStable => lifecycle == FeatureLifecycleStatus.stable;
  bool get isSuperseded => lifecycle == FeatureLifecycleStatus.superseded;
  int get activeDeltaHours =>
      (!included || isStable || isSuperseded) ? 0 : estimatedHours;

  Map<String, dynamic> toJson() => {
        'id': id,
        'title': title,
        'goal': goal,
        'doneWhen': doneWhen,
        'estimatedHours': estimatedHours,
        'included': included,
        'lifecycle': lifecycle.name,
        'originVersion': originVersion,
        if (supersedesFeatureTitle != null)
          'supersedesFeatureTitle': supersedesFeatureTitle,
        'inScope': inScope,
        'outOfScope': outOfScope,
        'tuningParams': tuningParams,
        'edgeCases': edgeCases,
        'checkpoints': checkpoints.map((c) => c.toJson()).toList(),
      };

  factory ProposedFeatureBlueprint.fromJson(Map<String, dynamic> json) {
    return ProposedFeatureBlueprint(
      id: json['id']?.toString() ?? 'feat',
      title: json['title']?.toString() ?? '',
      goal: json['goal']?.toString() ?? '',
      doneWhen: json['doneWhen']?.toString() ?? '',
      estimatedHours: (json['estimatedHours'] as num?)?.toInt() ?? 4,
      included: json['included'] != false,
      lifecycle: FeatureLifecycleStatus.fromString(json['lifecycle']?.toString()),
      originVersion: json['originVersion']?.toString() ?? 'v0.1',
      supersedesFeatureTitle: json['supersedesFeatureTitle']?.toString(),
      inScope: (json['inScope'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      outOfScope: (json['outOfScope'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      tuningParams: (json['tuningParams'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      edgeCases: (json['edgeCases'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      checkpoints: (json['checkpoints'] as List?)
              ?.whereType<Map<String, dynamic>>()
              .map(ProposedCheckpointBlueprint.fromJson)
              .toList() ??
          const <ProposedCheckpointBlueprint>[],
    );
  }
}

/// A proposed Playable Checkpoint inside a Feature Blueprint.
class ProposedCheckpointBlueprint {
  final String title;
  final String playtestCriteria;
  final List<String> tasks;
  final List<String> coveredScope;
  final List<String> tuningParams;
  final List<String> edgeCases;
  final String releaseVersion;

  const ProposedCheckpointBlueprint({
    required this.title,
    required this.playtestCriteria,
    required this.tasks,
    this.coveredScope = const [],
    this.tuningParams = const [],
    this.edgeCases = const [],
    this.releaseVersion = 'v0.1',
  });

  Map<String, dynamic> toJson() => {
        'title': title,
        'playtestCriteria': playtestCriteria,
        'tasks': tasks,
        'coveredScope': coveredScope,
        'tuningParams': tuningParams,
        'edgeCases': edgeCases,
        'releaseVersion': releaseVersion,
      };

  factory ProposedCheckpointBlueprint.fromJson(Map<String, dynamic> json) {
    return ProposedCheckpointBlueprint(
      title: json['title']?.toString() ?? '',
      playtestCriteria: json['playtestCriteria']?.toString() ?? '',
      tasks: (json['tasks'] as List?)?.map((e) => e.toString()).toList() ??
          const <String>[],
      coveredScope: (json['coveredScope'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      tuningParams: (json['tuningParams'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      edgeCases: (json['edgeCases'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      releaseVersion: json['releaseVersion']?.toString() ?? 'v0.1',
    );
  }
}

/// A proposed Core Loop Beat (Tier 3 Epic) inside a Release Blueprint.
class ProposedBeatBlueprint {
  String id;
  String title;
  String goal;
  String doneWhen;
  List<ProposedFeatureBlueprint> features;

  ProposedBeatBlueprint({
    required this.id,
    required this.title,
    required this.goal,
    required this.doneWhen,
    required this.features,
  });

  List<ProposedFeatureBlueprint> get includedFeatures =>
      features.where((f) => f.included && !f.isSuperseded).toList();

  List<ProposedFeatureBlueprint> get deferredFeatures =>
      features.where((f) => !f.included && !f.isSuperseded).toList();

  int get totalIncludedHours =>
      includedFeatures.fold(0, (sum, f) => sum + f.activeDeltaHours);

  Map<String, dynamic> toJson() => {
        'id': id,
        'title': title,
        'goal': goal,
        'doneWhen': doneWhen,
        'features': features.map((f) => f.toJson()).toList(),
      };

  factory ProposedBeatBlueprint.fromJson(Map<String, dynamic> json) {
    return ProposedBeatBlueprint(
      id: json['id']?.toString() ?? 'beat',
      title: json['title']?.toString() ?? '',
      goal: json['goal']?.toString() ?? '',
      doneWhen: json['doneWhen']?.toString() ?? '',
      features: (json['features'] as List?)
              ?.whereType<Map<String, dynamic>>()
              .map(ProposedFeatureBlueprint.fromJson)
              .toList() ??
          <ProposedFeatureBlueprint>[],
    );
  }
}

/// Blueprint produced by `ReleasePlannerAgent` for the Confirmation Gate (Stage 2).
class ReleaseBlueprint {
  final String releaseDocId;
  String releaseTitle;
  String releaseVersionTag;
  ReleaseScope preset;
  String goal;
  String doneWhen;
  List<AgentQuestion> questions;
  List<ProposedBeatBlueprint> beats;
  List<String> explicitExclusions;
  List<String> builtSoFar;
  List<String> missingGaps;
  String? lastAgentReply;

  ReleaseBlueprint({
    required this.releaseDocId,
    required this.releaseTitle,
    this.releaseVersionTag = 'v0.1',
    this.preset = ReleaseScope.featurePrototype,
    required this.goal,
    required this.doneWhen,
    required this.questions,
    required this.beats,
    this.explicitExclusions = const [],
    this.builtSoFar = const [],
    this.missingGaps = const [],
    this.lastAgentReply,
  });

  /// Total active delta hours of all currently checked/included Features across all Beats.
  int get totalIncludedHours =>
      beats.fold(0, (sum, b) => sum + b.totalIncludedHours);

  /// Total hours of all deferred (unchecked, non-superseded) Features across all Beats.
  int get totalDeferredHours => beats.fold(
        0,
        (sum, b) => sum + b.deferredFeatures.fold(0, (s, f) => s + f.estimatedHours),
      );

  /// Count of included Features across all Beats (excluding superseded ones).
  int get totalIncludedFeatures =>
      beats.fold(0, (sum, b) => sum + b.includedFeatures.length);

  /// Count of deferred Features across all Beats (excluding superseded ones).
  int get totalDeferredFeatures =>
      beats.fold(0, (sum, b) => sum + b.deferredFeatures.length);

  /// Combines explicit exclusions + any Features the user unchecked at the Confirmation Gate.
  List<String> get effectiveOutOfScope {
    final out = <String>[...explicitExclusions];
    for (final beat in beats) {
      for (final deferred in beat.deferredFeatures) {
        final label = '${deferred.title} (deferred from ${beat.title})';
        if (!out.contains(label)) {
          out.add(label);
        }
      }
    }
    return out;
  }

  Map<String, dynamic> toJson() => {
        'releaseDocId': releaseDocId,
        'releaseTitle': releaseTitle,
        'releaseVersionTag': releaseVersionTag,
        'preset': preset.name,
        'goal': goal,
        'doneWhen': doneWhen,
        'questions': questions.map((q) => q.toJson()).toList(),
        'beats': beats.map((b) => b.toJson()).toList(),
        'explicitExclusions': explicitExclusions,
        'builtSoFar': builtSoFar,
        'missingGaps': missingGaps,
        if (lastAgentReply != null) 'lastAgentReply': lastAgentReply,
      };

  factory ReleaseBlueprint.fromJson(Map<String, dynamic> json) {
    return ReleaseBlueprint(
      releaseDocId: json['releaseDocId']?.toString() ?? 'rel_v0_1',
      releaseTitle: json['releaseTitle']?.toString() ?? 'v0.1: Prototype',
      releaseVersionTag: json['releaseVersionTag']?.toString() ?? 'v0.1',
      preset: ReleaseScope.values.firstWhere(
        (s) => s.name == json['preset'],
        orElse: () => ReleaseScope.featurePrototype,
      ),
      goal: json['goal']?.toString() ?? '',
      doneWhen: json['doneWhen']?.toString() ?? '',
      questions: (json['questions'] as List?)
              ?.whereType<Map<String, dynamic>>()
              .map(AgentQuestion.fromJson)
              .toList() ??
          <AgentQuestion>[],
      beats: (json['beats'] as List?)
              ?.whereType<Map<String, dynamic>>()
              .map(ProposedBeatBlueprint.fromJson)
              .toList() ??
          <ProposedBeatBlueprint>[],
      explicitExclusions: (json['explicitExclusions'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      builtSoFar: (json['builtSoFar'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      missingGaps: (json['missingGaps'] as List?)
              ?.map((e) => e.toString())
              .toList() ??
          const <String>[],
      lastAgentReply: json['lastAgentReply']?.toString(),
    );
  }
}

/// Holds the Post-Release Retrospective & Auto-Carryover Summary (`v0.1` -> `v0.2`+).
class ReleaseRetrospectiveSummary {
  final String releaseTitle;
  final int totalFeatures;
  final int verifiedCheckpoints;
  final int totalCheckpoints;
  final int fixTasksTriaged;
  final int playtestGuardsAdded;
  final List<String> carryoverFeatureTitles;
  final List<String> hardenedFeatureTitles;

  const ReleaseRetrospectiveSummary({
    required this.releaseTitle,
    required this.totalFeatures,
    required this.verifiedCheckpoints,
    required this.totalCheckpoints,
    required this.fixTasksTriaged,
    required this.playtestGuardsAdded,
    required this.carryoverFeatureTitles,
    required this.hardenedFeatureTitles,
  });
}
